import type { Question } from '../../lib/types'

export const ec2_pricing_questions: Question[] = [
  { id: 'd4-pri-001', domain: 4, topics: ['EC2', 'pricing models', 'on-demand vs reserved'], type: 'single', stem: 'A company runs EC2 instances 24/7 for a production database that must always be available. What pricing model provides the most cost savings?', options: [{ id: 'A', text: 'Spot Instances' }, { id: 'B', text: 'Dedicated Instances' }, { id: 'C', text: 'On-Demand' }, { id: 'D', text: 'Reserved Instances (1-year or 3-year)' }], correct: ['D'], explanation: 'Reserved Instances provide up to 72% discount (3-year, all-upfront, Standard RI) for workloads that run continuously. For a 24/7 production database, the steady-state nature makes RIs the optimal choice. 1-year = up to 40% off; 3-year = up to 72% off.', distractors: { A: 'On-Demand has no commitment discount — appropriate for variable or unpredictable workloads only.', C: 'Spot Instances can be interrupted — not suitable for always-on production databases.', D: 'Dedicated Instances/Hosts are for compliance/licensing requirements — more expensive than standard Reserved Instances.' } },
  { id: 'd4-pri-002', domain: 4, topics: ['Spot Instances', 'interruption', 'savings'], type: 'single', stem: 'A batch processing job runs for 2 hours and can restart from checkpoints if interrupted. What EC2 pricing model reduces cost by up to 90%?', options: [{ id: 'A', text: '1-year Reserved Instances' }, { id: 'B', text: 'Dedicated Hosts' }, { id: 'C', text: 'Spot Instances' }, { id: 'D', text: 'On-Demand Instances' }], correct: ['C'], explanation: 'Spot Instances use spare AWS capacity at up to 90% off On-Demand pricing. When capacity is needed, AWS gives a 2-minute interruption notice. Fault-tolerant batch workloads with checkpointing are the ideal use case — they benefit from the discount and tolerate interruptions.', distractors: { A: 'On-Demand pricing provides no discount — appropriate only when Spot interruption is unacceptable.', C: 'Reserved Instances provide up to 72% discount for committed usage — not 90%, and require commitment.', D: 'Dedicated Hosts are for compliance/BYOL — more expensive than standard instances.' } },
  { id: 'd4-pri-003', domain: 4, topics: ['Savings Plans', 'Compute', 'flexibility'], type: 'single', stem: 'A company wants to commit to a spending level for EC2 to get discounts but needs flexibility to change instance families, regions, and even move workloads to Lambda or Fargate. What commitment type provides this?', options: [{ id: 'A', text: 'EC2 Instance Savings Plans (specific instance family/region)' }, { id: 'B', text: 'Compute Savings Plans' }, { id: 'C', text: 'Standard Reserved Instances (specific AZ/instance type)' }, { id: 'D', text: 'On-Demand Capacity Reservations' }], correct: ['B'], explanation: 'Compute Savings Plans provide the most flexibility: apply to any EC2 instance type, family, region, OS, and also to AWS Lambda and Fargate. Commit to a $/hour spend; up to 66% savings. No need to specify instance type — swap between families freely.', distractors: { A: 'EC2 Instance Savings Plans are locked to a specific instance family and region — provides up to 72% savings but less flexibility.', C: 'Standard Reserved Instances lock to specific AZ, instance type, and OS — maximum savings (up to 72%) but least flexibility.', D: 'On-Demand Capacity Reservations reserve capacity at On-Demand price — no discount.' } },
  { id: 'd4-pri-004', domain: 4, topics: ['Reserved Instances', 'Convertible', 'flexibility'], type: 'single', stem: 'A company purchases 1-year Standard Reserved Instances but expects to upgrade the instance type family before the term ends. What RI type allows changing instance attributes?', options: [{ id: 'A', text: 'Convertible Reserved Instances' }, { id: 'B', text: 'Spot Instances with savings' }, { id: 'C', text: 'Standard Reserved Instances' }, { id: 'D', text: 'Scheduled Reserved Instances' }], correct: ['A'], explanation: 'Convertible RIs allow exchanging for different instance families, sizes, OS, or tenancy during the term. Trade-off: lower maximum discount (up to 54%) vs. Standard (up to 72%). Exchange preserves the remaining RI value.', distractors: { A: 'Standard RIs can be modified within the same family (size changes) but cannot change instance family — Convertible RIs are needed for family changes.', C: 'Scheduled RIs are for predictable recurring capacity needs (e.g., every weekday 9-5) — no longer available to purchase.', D: 'Spot Instances don\'t provide reserved capacity or exchange flexibility.' } },
  { id: 'd4-pri-005', domain: 4, topics: ['Spot Instances', 'Spot Fleet', 'diversification'], type: 'single', stem: 'A Spot workload requires 100 vCPUs. Using a single instance type risks all instances being interrupted simultaneously. What strategy mitigates this?', options: [{ id: 'A', text: 'Use a single large instance type (fewer instances)' }, { id: 'B', text: 'Use On-Demand instances for all 100 vCPUs' }, { id: 'C', text: 'Reserve instances in multiple regions' }, { id: 'D', text: 'Spot Fleet with diversification across multiple instance types and AZs' }], correct: ['D'], explanation: 'Spot Fleet or Auto Scaling group with multiple instance types and AZs diversifies across Spot pools. Each pool (instance type + AZ combination) has its own interruption rate and price. When one pool is reclaimed, others continue running. The lowestPrice or capacityOptimized allocation strategies balance cost and availability.', distractors: { A: 'Fewer, larger instances concentrate risk — if the pool is reclaimed, all capacity is lost.', C: 'On-Demand for the entire workload eliminates the 70-90% cost savings.', D: 'Reserved instances don\'t apply to Spot usage.' } },
  { id: 'd4-pri-006', domain: 4, topics: ['EC2', 'Reserved Instance marketplace', 'sell'], type: 'single', stem: 'A company has unused Standard Reserved Instances for 8 months remaining. They no longer need the capacity. What can they do?', options: [{ id: 'A', text: 'Sell the unused Reserved Instances on the Reserved Instance Marketplace' }, { id: 'B', text: 'Transfer them to another account for free' }, { id: 'C', text: 'Convert them to On-Demand' }, { id: 'D', text: 'Request a refund from AWS' }], correct: ['A'], explanation: 'Standard Reserved Instances (not Convertible) can be listed on the Reserved Instance Marketplace. Sellers set the price; buyers get the remaining RI term at potentially lower prices. AWS charges a 12% service fee on the sale price.', distractors: { A: 'AWS doesn\'t offer RI refunds — the Marketplace is the exit strategy.', C: 'RIs cannot be "converted" to On-Demand — they are separate commitment products.', D: 'Transferring RIs requires going through the Marketplace (for Standard RIs) or using Savings Plans which are account-level commitments.' } },
  { id: 'd4-pri-007', domain: 4, topics: ['Spot Instances', 'interruption notice', '2 minutes'], type: 'single', stem: 'A Spot Instance receives an interruption notice. How much time does the instance have before termination?', options: [{ id: 'A', text: '30 seconds' }, { id: 'B', text: '10 minutes' }, { id: 'C', text: '2 minutes' }, { id: 'D', text: '1 hour' }], correct: ['C'], explanation: 'AWS provides a 2-minute interruption notice via EC2 instance metadata (http://169.254.169.254/latest/meta-data/spot/interruption-action) and an Amazon EventBridge event. Applications should detect this and gracefully save checkpoints/state within the 2-minute window.', distractors: { A: '30 seconds is insufficient for most checkpoint operations — 2 minutes is the correct window.', C: '10 minutes is too long — AWS gives 2 minutes specifically.', D: '1 hour notice would eliminate the need for rapid checkpointing design.' } },
  { id: 'd4-pri-008', domain: 4, topics: ['On-Demand Capacity Reservations', 'capacity guarantee'], type: 'single', stem: 'A company has a critical event in 2 weeks and needs guaranteed EC2 capacity in a specific AZ, even if not used beforehand. What product reserves capacity without a 1-year commitment?', options: [{ id: 'A', text: 'On-Demand Capacity Reservations' }, { id: 'B', text: 'Compute Savings Plans' }, { id: 'C', text: 'Reserved Instances (1-year minimum)' }, { id: 'D', text: 'Spot Instance requests (no capacity guarantee)' }], correct: ['A'], explanation: 'On-Demand Capacity Reservations ensure capacity is available in a specific AZ for a specific instance type. No term commitment — cancel anytime. Charged at On-Demand rate whether instances are running or not. Combine with Savings Plans/RIs to get discounts on reserved capacity.', distractors: { A: 'Reserved Instances require 1-year or 3-year commitment — too long for a 2-week event.', C: 'Spot doesn\'t guarantee capacity — capacity may not be available when needed.', D: 'Savings Plans commit to spending levels — don\'t reserve specific AZ/instance capacity.' } },
  { id: 'd4-pri-009', domain: 4, topics: ['EC2', 'instance types', 'right-sizing'], type: 'single', stem: 'EC2 instances are running at 10% average CPU utilization. They are paying for resources that are mostly idle. What cost optimization action should be taken first?', options: [{ id: 'A', text: 'Switch to Reserved Instances' }, { id: 'B', text: 'Purchase Compute Savings Plans' }, { id: 'C', text: 'Increase instance size for future growth' }, { id: 'D', text: 'Right-size the instances to a smaller type' }], correct: ['D'], explanation: 'Right-sizing should happen before any pricing commitment. AWS Compute Optimizer analyzes CloudWatch metrics and recommends optimal instance types. Reducing from m5.4xlarge to m5.large (if CPU usage supports it) can save 85% — more than any RI discount.', distractors: { A: 'Reserved Instances lock in the size — committing to the wrong (oversized) instance wastes money.', C: 'Scaling up already-oversized instances compounds the waste.', D: 'Savings Plans commit to spending levels — right-sizing first reduces the spending level you need to commit to.' } },
  { id: 'd4-pri-010', domain: 4, topics: ['Spot Instances', 'Spot Hibernate', 'stop'], type: 'single', stem: 'A Spot Instance runs a long-running stateful job. When interrupted, re-running from scratch takes 3 hours. What Spot interruption behavior preserves instance state without termination?', options: [{ id: 'A', text: 'Spot Fleet with multiple instances' }, { id: 'B', text: 'Spot Instance stop or hibernate' }, { id: 'C', text: 'Spot Instance termination (default)' }, { id: 'D', text: 'Spot Block (fixed duration)' }], correct: ['B'], explanation: 'Spot Instances can be configured with stop or hibernate behavior instead of terminate. Stop: instance goes to stopped state (EBS root volume preserved). Hibernate: RAM is saved to EBS; instance resumes with memory state intact. Both preserve state when capacity returns.', distractors: { A: 'Termination (default) destroys instance state — forces full restart.', C: 'Spot Fleet with multiple instances distributes interruption risk — doesn\'t prevent losing state on individual instance interruption.', D: 'Spot Blocks (fixed-duration) are no longer available for new usage since 2021.' } },
  { id: 'd4-pri-011', domain: 4, topics: ['EC2', 'Dedicated Hosts', 'BYOL'], type: 'single', stem: 'A company has a Windows Server license (per-socket) that can be used on AWS but only on dedicated physical servers with a known core count. What EC2 option supports Bring-Your-Own-License (BYOL) per-socket/per-core?', options: [{ id: 'A', text: 'Dedicated Hosts' }, { id: 'B', text: 'Dedicated Instances (isolated hardware, no control over physical host)' }, { id: 'C', text: 'Reserved Instances with dedicated tenancy' }, { id: 'D', text: 'On-Demand Instances with custom AMI' }], correct: ['A'], explanation: 'Dedicated Hosts provide a physical server with visibility into socket and core counts, enabling BYOL for per-socket/per-core licenses (Windows Server, SQL Server, etc.). You control instance placement on the host. More expensive but required for certain license compliance.', distractors: { A: 'Dedicated Instances run on hardware dedicated to you but you don\'t control placement or see socket/core topology — insufficient for per-socket BYOL.', C: 'Standard instances share hardware — per-socket BYOL requires dedicated physical host information.', D: 'RI with dedicated tenancy runs on dedicated hardware but doesn\'t provide the socket/core visibility needed for BYOL.' } },
  { id: 'd4-pri-012', domain: 4, topics: ['Auto Scaling', 'scheduled', 'predictable traffic'], type: 'single', stem: 'A news website has predictable traffic spikes every weekday at 8 AM (people reading morning news) that doubles normal load. Currently the team manually scales before 8 AM. What automates this?', options: [{ id: 'A', text: 'Target tracking auto scaling on CPU' }, { id: 'B', text: 'Dynamic scaling with step policies' }, { id: 'C', text: 'Predictive scaling (machine learning based)' }, { id: 'D', text: 'Scheduled scaling' }], correct: ['D'], explanation: 'Scheduled scaling pre-emptively adjusts capacity before the known traffic peak. This is more efficient than reactive auto scaling (which waits for CPU to spike before adding capacity). Also cheaper — instances are available exactly when needed.', distractors: { A: 'Target tracking reacts to current load — adds instances after the spike has already occurred, too late for morning peak.', C: 'Step scaling also reacts — can\'t pre-emptively prepare for known patterns.', D: 'Predictive scaling uses ML to predict patterns and schedule capacity — valid answer but scheduled scaling is simpler when the pattern is already known.' } },
  { id: 'd4-pri-013', domain: 4, topics: ['Savings Plans', 'EC2 Instance', 'specific family'], type: 'single', stem: 'A company commits to running M5 instances in us-east-1 for 1 year with no plans to change instance family or region. What Savings Plan type provides the highest discount for this specific commitment?', options: [{ id: 'A', text: 'EC2 Instance Savings Plans' }, { id: 'B', text: 'Convertible Reserved Instances (54%)' }, { id: 'C', text: 'Standard Reserved Instances (up to 72% but region-locked)' }, { id: 'D', text: 'Compute Savings Plans (up to 66%)' }], correct: ['A'], explanation: 'EC2 Instance Savings Plans: commit to a specific instance family in a specific region. Highest discount (up to 72%) with Savings Plan flexibility (can change instance size within the family, OS, tenancy). More flexible than RIs but locked to the family/region.', distractors: { A: 'Compute Savings Plans provide up to 66% — less than Instance Savings Plans for specific family/region commitments.', C: 'Convertible RIs provide up to 54% — less than Instance Savings Plans.', D: 'Standard RIs provide up to 72% but are locked to specific instance type+size, AZ, and OS — less flexible than Instance Savings Plans.' } },
  { id: 'd4-pri-014', domain: 4, topics: ['Spot', 'interruption', 'capacity-optimized'], type: 'single', stem: 'A Spot Fleet needs to minimize the frequency of Spot interruptions even if it doesn\'t always get the lowest price. What allocation strategy prioritizes availability over lowest cost?', options: [{ id: 'A', text: 'lowestPrice' }, { id: 'B', text: 'diversified' }, { id: 'C', text: 'capacityOptimized' }, { id: 'D', text: 'priceCapacityOptimized' }], correct: ['D'], explanation: 'priceCapacityOptimized is the recommended allocation strategy (AWS best practice since 2022). It identifies the Spot pools with the highest capacity availability (reducing interruptions) and then selects from those pools based on price. Balances both cost and availability.', distractors: { A: 'lowestPrice always picks the cheapest pool regardless of capacity depth — often leads to more interruptions.', B: 'capacityOptimized (without price) ignores cost — priceCapacityOptimized is the modern replacement.', C: 'diversified spreads across all pools equally — doesn\'t optimize for price or capacity.' } },
  { id: 'd4-pri-015', domain: 4, topics: ['EC2', 'pricing', 'per-second billing'], type: 'single', stem: 'An EC2 instance runs for 1 hour and 35 minutes, then is terminated. How is it billed?', options: [{ id: 'A', text: 'Billed for 1 hour and 35 minutes (5,700 seconds)' }, { id: 'B', text: 'Billed for 2 full hours' }, { id: 'C', text: 'Billed for 1.583 hours (fractional hours allowed)' }, { id: 'D', text: 'Billed for 1 full hour + 1 hour (rounded up to nearest hour)' }], correct: ['A'], explanation: 'EC2 charges per second (with a 1-minute minimum) for On-Demand, Reserved, and Spot instances. 1 hour 35 minutes = 5,700 seconds billed exactly. This enables cost-efficient short-duration jobs that were previously rounded up to full hours.', distractors: { A: 'Hourly billing was the old model before 2017 — EC2 now bills per second.', C: 'Rounding up to the nearest hour overstates the cost.', D: 'Fractional hours would be the same as per-second billing expressed differently — but the key point is per-second, not fractional.' } },
  { id: 'd4-pri-016', domain: 4, topics: ['Reserved Instances', 'payment options', 'all-upfront'], type: 'single', stem: 'A 3-year Reserved Instance costs $10,000 all-upfront, $11,500 partial-upfront ($5,000 + $187/month), or $14,000 no-upfront ($389/month × 36). Which provides the lowest total cost?', options: [{ id: 'A', text: 'Partial-upfront' }, { id: 'B', text: 'All options are equal in total cost' }, { id: 'C', text: 'No-upfront (monthly payments)' }, { id: 'D', text: 'All-upfront' }], correct: ['D'], explanation: 'All-upfront always provides the lowest total cost for Reserved Instances. The discount increases with: commitment length (3-year > 1-year) and upfront payment (all-upfront > partial > no-upfront). The trade-off is cash flow (larger initial outlay).', distractors: { A: 'No-upfront spreads payments but costs more total — $14,004 vs $10,000.', C: 'Partial-upfront balances cost and cash flow but isn\'t the cheapest option.', D: 'Different payment options explicitly have different total costs — all-upfront is always cheapest.' } },
  { id: 'd4-pri-017', domain: 4, topics: ['Spot Instances', 'persistence', 'one-time vs persistent'], type: 'single', stem: 'A Spot Instance request type is "one-time." The instance is interrupted. What happens next?', options: [{ id: 'A', text: 'The instance enters stopped state until Spot capacity returns' }, { id: 'B', text: 'AWS sends an alert and waits for manual re-submission' }, { id: 'C', text: 'The Spot request is not re-submitted' }, { id: 'D', text: 'AWS automatically restarts the Spot Instance' }], correct: ['C'], explanation: 'One-time Spot requests are fulfilled once. When interrupted, the instance is terminated and the request is closed — AWS does not automatically re-request capacity. Persistent Spot requests (type="persistent") automatically re-submit when the instance is interrupted, restarting when capacity returns.', distractors: { A: 'Persistent requests restart automatically — one-time requests do not.', C: 'Stop behavior requires configuring interruption action as "stop" — not the default for one-time requests.', D: 'AWS doesn\'t send manual restart alerts for one-time Spot requests.' } },
  { id: 'd4-pri-018', domain: 4, topics: ['EC2', 'Compute Optimizer', 'right-sizing'], type: 'single', stem: 'A company wants automated recommendations for right-sizing EC2 instances based on actual usage patterns. What AWS service provides ML-based recommendations?', options: [{ id: 'A', text: 'AWS Cost Explorer with RI recommendations' }, { id: 'B', text: 'AWS Compute Optimizer' }, { id: 'C', text: 'AWS Trusted Advisor cost checks' }, { id: 'D', text: 'AWS Config resource inventory' }], correct: ['B'], explanation: 'AWS Compute Optimizer uses ML to analyze EC2, Lambda, ECS on Fargate, and EBS metrics. Provides instance type recommendations with estimated savings and performance risk. Install the CloudWatch agent for memory metrics (not collected by default).', distractors: { A: 'Cost Explorer RI recommendations suggest RI coverage — not right-sizing instance types.', C: 'Trusted Advisor Cost Optimization checks flag obvious issues — Compute Optimizer provides deeper ML analysis.', D: 'AWS Config tracks resource configuration changes — not performance-based right-sizing recommendations.' } },
  { id: 'd4-pri-019', domain: 4, topics: ['Savings Plans', 'coverage', 'commitment'], type: 'single', stem: 'A company has 100 EC2 instances. AWS Cost Explorer shows 40% of EC2 spend is not covered by Savings Plans or Reserved Instances. What does this metric represent?', options: [{ id: 'A', text: 'Reserved Instance utilization rate' }, { id: 'B', text: 'On-Demand spend percentage' }, { id: 'C', text: 'The portion of EC2 compute spend not covered by any commitment discount' }, { id: 'D', text: 'Spot Instance usage percentage' }], correct: ['C'], explanation: 'Coverage rate measures what percentage of EC2 usage is covered by Reserved Instances or Savings Plans. 60% coverage = 40% On-Demand spend. Analyze which instances are uncovered and either purchase RIs/SPs to cover steady-state workloads or accept On-Demand pricing for variable ones.', distractors: { A: 'On-Demand spend percentage is one way to express it — but the context here is "coverage" rate which measures committed discount coverage.', C: 'Spot Instances are a separate pricing model — not part of RI/SP coverage metrics.', D: 'Utilization rate measures how much of a purchased RI is being used — different from coverage rate.' } },
  { id: 'd4-pri-020', domain: 4, topics: ['EC2', 'unused Reserved Instances', 'utilization'], type: 'single', stem: 'A company purchased Reserved Instances for 10 instances but now only runs 7. What is the utilization rate, and what happens to the cost of unused RIs?', options: [{ id: 'A', text: '70% utilization; unused RIs are charged at the RI rate regardless' }, { id: 'B', text: 'AWS automatically adjusts RI count to actual usage' }, { id: 'C', text: '70% utilization; unused RIs can be paused' }, { id: 'D', text: '70% utilization; unused RIs are refunded' }], correct: ['A'], explanation: 'RI utilization = actual usage / RI capacity. At 70% utilization, 3 RIs are wasted. You still pay for all 10 RIs — there is no refund. Options: (1) sell unused Standard RIs on the Marketplace, (2) modify RIs to apply to different instances in the same family, (3) increase usage to utilize purchased capacity.', distractors: { A: 'AWS does not refund unused RI capacity — commitment is binding.', C: 'RIs cannot be paused — you pay for the commitment regardless.', D: 'AWS doesn\'t auto-adjust RI count — you manage RI purchases and must match to actual usage.' } },
  { id: 'd4-pri-021', domain: 4, topics: ['EC2', 'Spot Block', 'fixed duration'], type: 'single', stem: 'A company wants to run a Spot Instance for exactly 3 hours with no interruption risk. What Spot option guarantees this?', options: [{ id: 'A', text: 'Spot Blocks (1-6 hour fixed duration)' }, { id: 'B', text: 'Persistent Spot request with a 3-hour duration' }, { id: 'C', text: 'No Spot option guarantees uninterrupted fixed duration' }, { id: 'D', text: 'Spot Fleet with capacityOptimized strategy' }], correct: ['C'], explanation: 'Spot Blocks (fixed duration 1-6 hours) were discontinued for new use in 2021. No current Spot option guarantees uninterrupted fixed duration. For guaranteed capacity, use On-Demand Capacity Reservations or Reserved Instances. For low interruption risk, use Spot with capacityOptimized strategy.', distractors: { A: 'Spot Blocks are no longer available — the exam may reference them as historical but they cannot be purchased today.', C: 'Persistent Spot requests re-request capacity after interruption — don\'t guarantee 3 continuous hours.', D: 'capacityOptimized reduces interruption frequency — doesn\'t guarantee a fixed duration.' } },
  { id: 'd4-pri-022', domain: 4, topics: ['EC2', 'T-instances', 'credits', 'burstable'], type: 'single', stem: 'A T3 instance has been at 100% CPU for 6 hours and CPU credit balance is 0. In standard mode, what happens?', options: [{ id: 'A', text: 'CPU is throttled to the baseline performance level' }, { id: 'B', text: 'The instance migrates to an M5 instance type' }, { id: 'C', text: 'The instance is terminated' }, { id: 'D', text: 'The instance automatically upgrades to unlimited mode' }], correct: ['A'], explanation: 'T instances earn CPU credits at baseline. When credits are exhausted in standard mode, CPU is throttled to the baseline rate (e.g., T3.micro baseline = 10% vCPU). The instance continues running. In unlimited mode, additional CPU is available at extra per-vCPU-hour charges.', distractors: { A: 'CPU credit exhaustion doesn\'t terminate instances — performance is degraded.', C: 'Unlimited mode must be explicitly enabled — standard mode throttles to baseline.', D: 'Instance type migration is not automatic — instances stay on the same type.' } },
  { id: 'd4-pri-023', domain: 4, topics: ['Savings Plans', 'purchase', 'timing'], type: 'single', stem: 'A company wants to purchase Savings Plans. AWS recommends analyzing 7-14 days of usage. What tool in AWS shows recommended Savings Plan commitments based on usage history?', options: [{ id: 'A', text: 'AWS Config' }, { id: 'B', text: 'AWS Compute Optimizer' }, { id: 'C', text: 'AWS Trusted Advisor' }, { id: 'D', text: 'AWS Cost Explorer Savings Plans recommendations' }], correct: ['D'], explanation: 'Cost Explorer provides Savings Plans recommendations based on historical usage (7/30/60-day lookback). Shows recommended hourly commitment, estimated coverage, and projected savings. Helps right-size commitment before purchase.', distractors: { A: 'AWS Config tracks resource configurations — not billing optimization recommendations.', C: 'Trusted Advisor has some cost optimization checks but doesn\'t provide Savings Plans purchase recommendations with amounts.', D: 'Compute Optimizer recommends instance types — not Savings Plans commitment amounts.' } },
  { id: 'd4-pri-024', domain: 4, topics: ['EC2', 'hibernation', 'cost'], type: 'single', stem: 'Development EC2 instances run 8 hours/day (workday) but are left running 24/7. What action reduces EC2 cost for these instances by 67%?', options: [{ id: 'A', text: 'Downsize to smaller instance types' }, { id: 'B', text: 'Use Spot Instances for development' }, { id: 'C', text: 'Stop (or hibernate) instances after work hours using AWS Instance Scheduler or Lambda; only pay for compute when instances are running' }, { id: 'D', text: 'Switch to Reserved Instances' }], correct: ['C'], explanation: 'Stopped EC2 instances don\'t incur compute charges (only EBS storage charges). Running 8/24 hours = 67% cost reduction. AWS Instance Scheduler automates start/stop on a schedule. This is the #1 optimization for non-production/development environments.', distractors: { A: 'Reserved Instances commit to 24/7 usage — worse for dev instances that only run 8/24 hours.', C: 'Downsizing helps but running 24/7 still costs more than stopping 16 hours/day.', D: 'Spot for development works but interruptions disrupt work — stop/hibernate is simpler.' } },
  { id: 'd4-pri-025', domain: 4, topics: ['EC2', 'pricing', 'regions'], type: 'single', stem: 'A workload can run in any AWS region. EC2 pricing varies by region. Which region typically has the lowest EC2 On-Demand prices?', options: [{ id: 'A', text: 'ap-south-1 (Mumbai)' }, { id: 'B', text: 'us-east-1 (N. Virginia)' }, { id: 'C', text: 'eu-west-1 (Ireland)' }, { id: 'D', text: 'All regions have identical pricing' }], correct: ['B'], explanation: 'us-east-1 (N. Virginia) is typically the cheapest AWS region for EC2 and most services. It\'s also where new instance types and features launch first. For cost-sensitive batch workloads without latency requirements, deploying in us-east-1 provides meaningful savings.', distractors: { A: 'eu-west-1 pricing is higher than us-east-1 — European regions have slightly higher costs.', C: 'ap-south-1 pricing doesn\'t reflect labor costs — AWS pricing is primarily based on infrastructure costs and market factors.', D: 'AWS pricing explicitly varies by region — region selection is a cost lever.' } },
  { id: 'd4-pri-026', domain: 4, topics: ['EC2 Auto Scaling', 'cooldown', 'cost'], type: 'single', stem: 'An Auto Scaling group adds instances rapidly during a traffic spike. By the time the last instances are healthy, the spike is already over. This wastes money on unnecessary instances. What helps?', options: [{ id: 'A', text: 'Disable scale-in protection' }, { id: 'B', text: 'Increase the cooldown period to prevent rapid scaling' }, { id: 'C', text: 'Reduce the scale-in cooldown so instances are terminated faster when traffic drops; use target tracking instead of step scaling for more responsive cost control' }, { id: 'D', text: 'Use Reserved Instances for the Auto Scaling group' }], correct: ['C'], explanation: 'Fast scale-in removes unnecessary instances quickly. Target tracking policies automatically adjust the target metric and can scale down smoothly. A short scale-in cooldown (default 300s) reduces time running unneeded instances. Predictive scaling anticipates future demand.', distractors: { A: 'Longer cooldown delays scale-in — the opposite of what\'s needed.', C: 'Reserved Instances commit to a fixed number — don\'t help with dynamic over-provisioning.', D: 'Scale-in protection prevents specific instances from being terminated — useful for stateful instances but not general cost control.' } },
  { id: 'd4-pri-027', domain: 4, topics: ['Spot Instances', 'spot price', 'bidding'], type: 'single', stem: 'When requesting Spot Instances, does setting a higher "max price" bid increase the chances of getting the instance?', options: [{ id: 'A', text: 'Yes' }, { id: 'B', text: 'Bids above On-Demand price guarantee uninterrupted access' }, { id: 'C', text: 'Spot pricing doesn\'t use bids anymore' }, { id: 'D', text: 'Only partially' }], correct: ['C'], explanation: 'AWS deprecated traditional Spot bidding in 2017. Spot pricing is now market-based and fluctuates continuously. Setting a max price above the current Spot price means you won\'t be interrupted due to price exceeding your bid. Capacity availability (not bid price) is the primary driver of Spot availability.', distractors: { A: 'Spot allocation is not an auction where higher bids win — it\'s capacity-based.', B: 'Partially correct but C is more accurate about the current model.', D: 'Setting max price at On-Demand rate means you won\'t be interrupted for price reasons — but capacity reclamation can still interrupt.' } },
  { id: 'd4-pri-028', domain: 4, topics: ['EC2', 'graviton', 'savings'], type: 'single', stem: 'A company runs 100 x86 EC2 m5.2xlarge instances. After testing, Graviton3 (m7g.2xlarge) provides equal performance. What is the approximate cost savings?', options: [{ id: 'A', text: 'Approximately 20% lower cost for Graviton vs. comparable Intel/AMD x86 instances; better price-performance' }, { id: 'B', text: '50% savings' }, { id: 'C', text: '90% savings like Spot Instances' }, { id: 'D', text: 'No savings' }], correct: ['A'], explanation: 'Graviton instances (ARM-based) typically cost 10-20% less than comparable x86 (Intel/AMD) instances. Graviton3 also often provides better performance per dollar. For containerized workloads (easily recompiled), switching to Graviton is a straightforward cost optimization.', distractors: { A: 'Graviton is explicitly priced lower than comparable Intel instances — typically 10-20% cheaper.', C: '50% savings would be exceptional — Graviton typically provides 10-20% cost savings.', D: 'Graviton savings are 10-20%, not 90% like Spot Instances.' } },
  { id: 'd4-pri-029', domain: 4, topics: ['EC2', 'Reserved Instances', 'AZ vs regional'], type: 'single', stem: 'Standard Reserved Instances can be purchased as AZ-specific (zonal) or regional. What is the key advantage of regional (not AZ-specific) RIs?', options: [{ id: 'A', text: 'Regional RIs provide capacity reservations' }, { id: 'B', text: 'Regional RIs provide higher discounts' }, { id: 'C', text: 'Regional RIs apply the discount across all AZs in the region and across instance sizes in the same family (instance size flexibility); no capacity reservation' }, { id: 'D', text: 'Regional RIs can be used across multiple regions' }], correct: ['C'], explanation: 'Regional RIs provide instance size flexibility (an m5.2xlarge RI applies the discount to equivalent capacity in m5.large, m5.xlarge, etc.) and apply across all AZs in the region. However, they do NOT provide capacity reservation. Zonal RIs reserve specific AZ capacity but lack size flexibility.', distractors: { A: 'The opposite is true — zonal RIs provide capacity reservation; regional RIs do not.', C: 'Discount rates are the same for regional and zonal RIs — flexibility is the differentiator.', D: 'Regional RIs apply within one region only — not across multiple regions.' } },
  { id: 'd4-pri-030', domain: 4, topics: ['Savings Plans', 'utilization', 'coverage'], type: 'single', stem: 'A Savings Plan is purchased at $5/hour but actual usage only hits $3/hour during off-peak periods. What is the utilization rate and what are the cost implications?', options: [{ id: 'A', text: '60% utilization; extra $2/hour is automatically transferred to another account' }, { id: 'B', text: 'Savings Plans auto-adjust to actual usage' }, { id: 'C', text: '60% utilization; the unused $2/hour commitment is refunded' }, { id: 'D', text: '60% utilization; the full $5/hour is charged regardless of usage' }], correct: ['D'], explanation: 'Savings Plans are a spending commitment — you pay the committed $/hour whether or not you consume that level of compute. Low utilization means you\'re paying for unused commitment. Target 80-90%+ utilization when sizing Savings Plans — don\'t over-commit.', distractors: { A: 'No refunds for unused Savings Plans commitment — it\'s a binding financial commitment.', C: 'Savings Plans cannot be transferred between accounts post-purchase.', D: 'Savings Plans have a fixed commitment — no automatic adjustment.' } },
  { id: 'd4-pri-031', domain: 4, topics: ['EC2', 'Spot', 'checkpointing'], type: 'single', stem: 'A machine learning training job uses Spot Instances and runs for 8 hours total. Without checkpointing, if the instance is interrupted at hour 6, all 6 hours of training are lost. What is the recommended architectural pattern?', options: [{ id: 'A', text: 'Save model checkpoints to S3 every 30 minutes; on Spot interruption, the job restarts from the last checkpoint' }, { id: 'B', text: 'Use dedicated instances for ML training' }, { id: 'C', text: 'Use multiple Spot instances simultaneously' }, { id: 'D', text: 'Run ML training only on On-Demand instances' }], correct: ['A'], explanation: 'Regular checkpointing to S3 limits re-work on Spot interruption. Most ML frameworks (TensorFlow, PyTorch) support checkpoint callbacks. On restart, load the latest checkpoint from S3. Running 8 hours on Spot with checkpointing saves 70-90% vs. On-Demand with minimal re-work.', distractors: { A: 'On-Demand eliminates interruption risk but at 3-10x the cost of Spot — not cost-optimized.', C: 'Dedicated instances are for BYOL licensing — not Spot interruption mitigation.', D: 'Multiple simultaneous Spot instances parallelize training but don\'t protect against interruption without checkpointing.' } },
  { id: 'd4-pri-032', domain: 4, topics: ['EC2', 'Reserved Instance', 'apply rules'], type: 'single', stem: 'A company purchases a 1-year Regional RI for m5.xlarge. They are currently running m5.2xlarge instances. Can the RI discount apply?', options: [{ id: 'A', text: 'No' }, { id: 'B', text: 'Yes' }, { id: 'C', text: 'Only if the m5.2xlarge is in the same AZ' }, { id: 'D', text: 'Only for Linux instances' }], correct: ['B'], explanation: 'Regional RIs (Linux/Unix shared tenancy) have instance size flexibility within the same instance family. An m5.xlarge RI (8 vCPUs) covers 50% of an m5.2xlarge (16 vCPUs). The normalization factor determines coverage. This flexibility prevents wasted RI capacity when instance sizes change.', distractors: { A: 'Exact match is required for zonal RIs — regional RIs have size flexibility.', C: 'Regional RIs apply across all AZs — AZ doesn\'t matter.', D: 'Instance size flexibility applies to Linux/Unix — Windows RIs require exact instance type match.' } },
  { id: 'd4-pri-033', domain: 4, topics: ['EC2', 'Spot', 'interruption handling'], type: 'single', stem: 'Before a Spot Instance is interrupted, how can the application detect the impending termination programmatically?', options: [{ id: 'A', text: 'SNS notification from EC2 Spot service' }, { id: 'B', text: 'Subscribe to AWS Health service for Spot events' }, { id: 'C', text: 'Poll the EC2 instance metadata service: curl http://169.254.169.254/latest/meta-data/spot/termination-time' }, { id: 'D', text: 'CloudWatch alarm on Spot price exceeding max bid' }], correct: ['C'], explanation: 'Spot interruption notice is available via the instance metadata service (IMDS). Applications can poll this endpoint periodically (e.g., every 5 seconds). When an interruption is scheduled, the endpoint returns the termination time. Also available via EventBridge (EC2 Spot Instance Interruption Warning event).', distractors: { A: 'AWS Health provides account-level event notifications — not instance-level interruption detection via metadata.', C: 'CloudWatch alarms on Spot price are backward-looking — the metadata polling approach gives the 2-minute window warning.', D: 'EC2 Spot sends EventBridge events — the metadata approach is in-instance; EventBridge is for external notifications.' } },
  { id: 'd4-pri-034', domain: 4, topics: ['Reserved Instances', 'scheduled', 'recurring'], type: 'single', stem: 'A workload runs every weekday 9 AM-5 PM (8 hours). Purchasing a full 1-year RI (24/7) wastes 67% of capacity. What product was designed for recurring, predictable-hours workloads?', options: [{ id: 'A', text: 'On-Demand with instance scheduler (recommended current approach)' }, { id: 'B', text: 'T3 instances with CPU credits' }, { id: 'C', text: 'Spot Instances with a persistent request' }, { id: 'D', text: 'Scheduled Reserved Instances' }], correct: ['A'], explanation: 'Scheduled Reserved Instances have been deprecated. The current recommended approach is On-Demand instances with AWS Instance Scheduler (auto start/stop) or Auto Scaling scheduled actions. For this pattern: run 8/24 hours on On-Demand = 67% less compute time; combine with Savings Plans to discount On-Demand.', distractors: { A: 'Spot persistent requests restart instances automatically — but risk interruption during the 8-hour window.', B: 'Scheduled RIs were discontinued — this is exam knowledge but they\'re no longer purchasable.', D: 'T3 instances are burstable — unrelated to scheduling periodic workloads.' } },
  { id: 'd4-pri-035', domain: 4, topics: ['EC2', 'pricing', 'free tier'], type: 'single', stem: 'A new AWS account wants to run a micro web application for free for 12 months. What EC2 instance is included in the AWS Free Tier?', options: [{ id: 'A', text: 't2.micro or t3.micro (where available)' }, { id: 'B', text: 'Any instance below 2 vCPU' }, { id: 'C', text: 'm5.large' }, { id: 'D', text: 't3.micro' }], correct: ['A'], explanation: 'AWS Free Tier includes 750 hours/month of t2.micro or t3.micro EC2 (where t2 is not available) for 12 months from account creation. This covers one continuously running micro instance. Charges apply for additional instances, storage beyond free tier, and data transfer.', distractors: { A: 't3.micro is included in some regions — the primary Free Tier offering is t2.micro; t3.micro is included where t2 is not available.', C: 'm5.large is not part of the EC2 Free Tier — only t2/t3.micro.', D: 'Free Tier is based on specific instance type (t2.micro/t3.micro) — not a generic vCPU threshold.' } },
  { id: 'd4-pri-036', domain: 4, topics: ['EC2', 'cost allocation', 'tagging'], type: 'single', stem: 'A company with multiple teams sharing an AWS account needs to identify which team is spending the most on EC2. What is the prerequisite for team-level cost allocation?', options: [{ id: 'A', text: 'Separate AWS accounts per team' }, { id: 'B', text: 'Use AWS Cost Categories with manual rules' }, { id: 'C', text: 'Apply consistent cost allocation tags (e.g., Team=Engineering) to all EC2 resources; activate tags in AWS Billing for Cost Explorer filtering' }, { id: 'D', text: 'Create VPCs per team' }], correct: ['C'], explanation: 'Cost allocation tags must be applied consistently to resources and activated in Billing settings. Once activated, Cost Explorer can filter and group costs by tag. Tagging is the foundation of multi-team cost visibility within a single account.', distractors: { A: 'Separate accounts provide stronger isolation — but cost allocation tags work within a single account.', C: 'Cost Categories aggregate costs using rules — tags are still needed as the raw data source.', D: 'VPC separation helps with network isolation — doesn\'t provide billing cost allocation.' } },
  { id: 'd4-pri-037', domain: 4, topics: ['Spot', 'Spot and Reserved', 'architecture'], type: 'single', stem: 'A web application uses Auto Scaling. The team wants to minimize cost: baseline traffic served by discounted committed instances, and peak burst served by cheap Spot. What architecture achieves this?', options: [{ id: 'A', text: 'Reserved/Savings Plans for baseline On-Demand (say, 3 instances) + Spot Fleet for burst' }, { id: 'B', text: 'Dedicated Hosts for security' }, { id: 'C', text: 'All Spot for 90% savings' }, { id: 'D', text: 'All On-Demand for reliability' }], correct: ['A'], explanation: 'Best practice: committed instances (RI/SP) for baseline minimum capacity + Spot for burst. If Spot is interrupted during a surge, the RI baseline still serves traffic. This combines maximum savings on committed capacity with Spot economics for variable load.', distractors: { A: 'All Spot risks complete capacity loss during interruption — baseline service may fail.', C: 'All On-Demand misses 40-90% savings available from RI/Spot.', D: 'Dedicated Hosts are for BYOL/compliance — more expensive than standard instances.' } },
  { id: 'd4-pri-038', domain: 4, topics: ['EC2', 'instance lifecycle', 'stop vs terminate'], type: 'single', stem: 'A developer stops an EC2 instance for 30 days and then starts it again. What charges apply during the stopped period?', options: [{ id: 'A', text: 'Full On-Demand hourly rate' }, { id: 'B', text: 'Half the On-Demand hourly rate' }, { id: 'C', text: 'Reserved Instance rate if purchased' }, { id: 'D', text: 'No compute charges; EBS root volume and EIP charges continue; Elastic IP is charged if not attached to a running instance' }], correct: ['D'], explanation: 'Stopped EC2 instances don\'t incur compute charges. However: EBS volumes continue to be charged (even for stopped instances), Elastic IPs are charged when not associated with a running instance, and Reserved Instance charges still apply if purchased.', distractors: { A: 'Compute charges stop when the instance is stopped — only EBS and EIP charges continue.', C: 'There is no "half rate" for stopped instances — compute is either running (charged) or stopped (not charged).', D: 'RI charges apply to the account even when instances are stopped — you still pay the RI rate.' } },
  { id: 'd4-pri-039', domain: 4, topics: ['EC2', 'cost optimization', 'containerize'], type: 'single', stem: 'An application runs on 20 separate EC2 instances (one service per instance), each at 15-20% CPU utilization. What architectural change could reduce EC2 instance count significantly?', options: [{ id: 'A', text: 'Containerize services with ECS/EKS' }, { id: 'B', text: 'Use one large EC2 instance for all services' }, { id: 'C', text: 'Switch all to Lambda' }, { id: 'D', text: 'Right-size each instance to a smaller type' }], correct: ['A'], explanation: 'Containerization enables bin packing — multiple services share the same EC2 instance. At 15-20% CPU per service, one m5.4xlarge can potentially run 5-6 services instead of 5-6 separate smaller instances. ECS/EKS manages scheduling and placement.', distractors: { A: 'Right-sizing each service to a smaller instance reduces waste — but containers enable much denser packing.', C: 'Lambda works for event-driven services — not appropriate for all microservices (especially those with persistent connections or long-running processes).', D: 'One large instance is a single point of failure — containers with a container orchestration platform provides better isolation.' } },
  { id: 'd4-pri-040', domain: 4, topics: ['EC2', 'Spot interruption', 'strategies'], type: 'single', stem: 'A stateless web server fleet uses Spot Instances. An interruption causes all instances to be reclaimed simultaneously. What strategy prevents full service outage on mass interruption?', options: [{ id: 'A', text: 'Disable CloudWatch monitoring' }, { id: 'B', text: 'Use a single large Spot instance' }, { id: 'C', text: 'Use multiple instance types across multiple AZs' }, { id: 'D', text: 'Set max price to On-Demand rate' }], correct: ['C'], explanation: 'Spot pool diversification is the primary Spot availability strategy. Each combination of (instance type, AZ) is an independent pool. When one pool is reclaimed, other pools continue running. Use Spot Fleet or Auto Scaling groups with multiple instance types and AZs.', distractors: { A: 'One large instance concentrates all capacity in one Spot pool — maximum risk of total outage.', C: 'On-Demand max price prevents interruption due to price exceeding max — not capacity reclamation.', D: 'CloudWatch monitoring doesn\'t affect Spot availability.' } },
  { id: 'd4-pri-041', domain: 4, topics: ['AWS Cost Explorer', 'RI recommendations', 'coverage'], type: 'single', stem: 'A company wants a tool that analyzes EC2 usage patterns and recommends which Reserved Instances to purchase. Where is this built into AWS?', options: [{ id: 'A', text: 'AWS Config recommendations' }, { id: 'B', text: 'AWS Systems Manager Inventory' }, { id: 'C', text: 'AWS Trusted Advisor' }, { id: 'D', text: 'AWS Cost Explorer Reserved Instance recommendations' }], correct: ['D'], explanation: 'Cost Explorer has an RI recommendations feature under "Reservations." It analyzes your actual On-Demand usage, calculates optimal RI purchases, and shows estimated savings. Choose lookback period (7/30/60 days) and payment option to customize recommendations.', distractors: { A: 'AWS Config tracks resource configurations and compliance — not billing recommendations.', C: 'Trusted Advisor has RI utilization and coverage checks — Cost Explorer provides the purchase recommendations.', D: 'Systems Manager Inventory tracks software inventory — not billing optimization.' } },
  { id: 'd4-pri-042', domain: 4, topics: ['EC2', 'Spot Fleet', 'target capacity'], type: 'single', stem: 'A Spot Fleet is configured for a target capacity of 100 vCPUs. Some instances are interrupted. What does Spot Fleet do automatically?', options: [{ id: 'A', text: 'Spot Fleet automatically replenishes interrupted instances by requesting new Spot capacity in other pools to maintain the target capacity' }, { id: 'B', text: 'Spot Fleet terminates all remaining instances' }, { id: 'C', text: 'Spot Fleet sends an email notification only' }, { id: 'D', text: 'Nothing' }], correct: ['A'], explanation: 'Spot Fleet maintains the target capacity. When instances are interrupted, Spot Fleet automatically launches replacement instances from other Spot pools (if capacity is available) to restore the target. The maintain strategy (default) vs. request strategy (one-time launch) determines this behavior.', distractors: { A: 'The maintain strategy (default) actively replenishes interrupted capacity — not nothing.', C: 'Spot Fleet doesn\'t terminate remaining instances when some are interrupted.', D: 'Notifications may be sent via CloudWatch Events — but the primary behavior is automated replenishment.' } },
  { id: 'd4-pri-043', domain: 4, topics: ['EC2', 'cost efficiency', 'newer generations'], type: 'single', stem: 'A company is running m4.xlarge instances (3rd generation). AWS releases m7i.xlarge at a lower price with better performance. What is the cost optimization recommendation?', options: [{ id: 'A', text: 'Keep m4.xlarge' }, { id: 'B', text: 'Scale out m4.xlarge instances to compensate' }, { id: 'C', text: 'Migrate to newer generation (m7i.xlarge)' }, { id: 'D', text: 'Switch to m4.2xlarge for twice the capacity at same price' }], correct: ['C'], explanation: 'Each EC2 generation typically offers 10-15% better price-performance. Migrating from m4 to m7i provides approximately 40% better performance per dollar. Apply Savings Plans (instance family flexibility) to avoid RI conversion issues. AWS recommends upgrading to current generations.', distractors: { A: 'Older generation instances are often more expensive per vCPU/memory than newer generations.', C: 'More old-generation instances is costlier than fewer new-generation instances providing the same throughput.', D: 'M4.2xlarge is double the m4.xlarge — higher cost, still older generation.' } },
  { id: 'd4-pri-044', domain: 4, topics: ['EC2', 'burstable', 'standard mode vs unlimited'], type: 'single', stem: 'A T3 instance in unlimited mode sustains 100% CPU for 24 hours beyond the credit balance. How is the excess CPU billed?', options: [{ id: 'A', text: 'Charged at $0.05 per vCPU-hour for CPU usage above the baseline (Linux)' }, { id: 'B', text: 'No extra charge' }, { id: 'C', text: 'Billed at standard On-Demand rate for a larger instance' }, { id: 'D', text: 'The instance is automatically upgraded to an M5' }], correct: ['A'], explanation: 'T3 unlimited mode allows sustained CPU above baseline at $0.05/vCPU-hour (Linux) or $0.096/vCPU-hour (Windows). For applications that need frequent CPU bursting, unlimited mode prevents throttling but can result in unexpected charges if CPU usage is consistently high.', distractors: { A: 'Unlimited mode incurs additional charges for sustained above-baseline CPU — not free.', C: 'Instance type doesn\'t change automatically.', D: 'The billing model is explicit vCPU-hour charges above baseline — not the hourly rate of a larger instance.' } },
  { id: 'd4-pri-045', domain: 4, topics: ['EC2', 'pricing', 'data transfer'], type: 'single', stem: 'An EC2 instance in us-east-1 transfers 1 TB of data to another EC2 instance in us-west-2 in the same AWS account. What is the data transfer cost?', options: [{ id: 'A', text: 'Free' }, { id: 'B', text: 'Free if using VPC peering' }, { id: 'C', text: 'Free via AWS backbone (not internet)' }, { id: 'D', text: 'Cross-region data transfer is charged (~$0.02/GB) even within the same account' }], correct: ['D'], explanation: 'Cross-region data transfer is charged regardless of account ownership — ~$0.02/GB from us-east-1 to us-west-2. This applies to EC2, S3, and most other services. Design architectures to minimize cross-region data transfer or use services like CloudFront to reduce egress costs.', distractors: { A: 'Same account doesn\'t exempt cross-region data transfer costs.', C: 'Cross-region VPC peering is charged at standard inter-region data transfer rates — free peering only applies within the same region.', D: 'AWS backbone routing doesn\'t make cross-region transfers free — the charge reflects infrastructure costs.' } },
]
